{
  "hypothesis": "Short-term reversal following abnormal volume spikes in small-cap stocks",
  "factors": [
    {
      "name": "VolumeReversalDepth",
      "expression": "TS_ZSCORE(TS_ARGMAX($volume, 30), 60)",
      "explanation": "This factor explores the DEPTH axis by finding the day with the highest volume over 30 days and then normalizing its impact on returns over 60 days, capturing the reversal effect after a spike."
    },
    {
      "name": "VolumeSkewReversal",
      "expression": "TS_SKEW($return, 60) - TS_SKEW($volume, 30)",
      "explanation": "This factor explores the SHAPE, NOT LEVEL axis by comparing the skewness of returns and volume over different time horizons, highlighting asymmetries in price and volume dynamics."
    },
    {
      "name": "ResidualVolumeImpact",
      "expression": "TS_ZSCORE(REGRESI($return, $volume, 60), 30)",
      "explanation": "This factor explores the RESIDUAL axis by regressing returns on volume and normalizing the residuals, isolating the portion of return variation unexplained by volume, which may reflect reversal effects."
    },
    {
      "name": "VolumeMomentumContrast",
      "expression": "TS_PCTCHANGE($volume, 5) / TS_PCTCHANGE($return, 1)",
      "explanation": "This factor explores the TIMESCALE CONTRAST axis by comparing the momentum of volume and returns over different periods, capturing how volume spikes influence return trends."
    },
    {
      "name": "VolumeRankReversal",
      "expression": "RANK(TS_ZSCORE($volume, 20)) - RANK(TS_ZSCORE($return, 60))",
      "explanation": "This factor explores the ODD NORMALISATION axis by ranking normalized volume and returns separately, revealing the relative positioning of stocks in terms of volume and performance."
    },
    {
      "name": "VolumeShapeAsymmetry",
      "expression": "SIGN($volume - TS_MED($volume, 20)) * TS_PCTCHANGE($return, 1)",
      "explanation": "This factor explores the ASYMMETRY axis by assessing how changes in returns relate to deviations in volume from its median, identifying asymmetric responses to volume shocks."
    }
  ]
}

